package com.citi.put.checks.studio.guided.publication;
import com.citi.put.checks.studio.dispatch.StudioDispatchLedgerStatements;
import com.citi.put.checks.studio.secrets.SecretUseAuditRecorder;
import com.citi.put.checks.studio.secrets.SecretAuditLifecycle;
import java.time.Instant;
public final class TerminalConstraintProbe {
 public static void main(String[] args) throws Exception {
  try (var f=GuidedSecretLoginMigrationTest.publishedRetry()) {
   System.out.println("OWN_DISPOSABLE_FIXTURE_CREATED");
   var ledger=new StudioDispatchLedgerStatements(f.jdbc());
   ledger.installSecretAudit(new SecretAuditLifecycle(f.jdbc(),new SecretUseAuditRecorder(f.jdbc())));
   f.transaction().executeWithoutResult(t -> {
    if(ledger.closeWithError(f.id(),"DISPATCH_FAILED",Instant.now())!=1)throw new AssertionError("No winner");
    f.jdbc().execute("SET CONSTRAINTS ALL IMMEDIATE");
    System.out.println("GUARD_VALIDATED_BEFORE_MUTATION");
    int changed=f.jdbc().update("UPDATE ui_test_executions SET error_code='DISPATCH_UNKNOWN',ended_at=ended_at+interval '1 second',snapshot_revision=snapshot_revision+1 WHERE id=?",f.id());
    System.out.println("POST_VALIDATION_HISTORY_MUTATION_ROWS="+changed);
   });
   System.out.println("COMMITTED_INCONSISTENCY="+f.jdbc().queryForObject("SELECT count(*) FROM studio_observed_terminal_secret_settlements s JOIN ui_test_executions e ON e.id=s.execution_id AND e.started_at=s.execution_accepted_at JOIN studio_dispatch_ledger l ON l.execution_id=e.id WHERE s.terminal_error_code<>e.error_code AND s.terminal_ended_at<>e.ended_at AND e.snapshot_revision<>s.before_snapshot_revision+1 AND l.terminal_error_code<>e.error_code",Integer.class));
  }
  System.out.println("OWN_DISPOSABLE_FIXTURE_CLOSED");
 }
}
